<?php
// 2026-10-04：营业执照与完整 OCR 资料均在当前页弹窗查看，避免跳转丢失管理上下文。
$verificationLabels=['none'=>['未认证','muted'],'draft'=>['草稿','muted'],'pending'=>['待审核','warning'],'approved'=>['已认证','success'],'rejected'=>['已驳回','danger'],'suspended'=>['已暂停','danger']];
$recognitionLabels=['consumer'=>'普通用户','suspected'=>'疑似商家','confirmed'=>'行为确认商家','verified'=>'认证商家'];
$ocrQuota=max(0,(int)setting('wechat.ocr.daily_quota','100'));
$ocrQuotaDay=(new \DateTimeImmutable('now',new \DateTimeZone('Asia/Shanghai')))->format('Y-m-d');
$ocrUsed=0;$ocrCounterReady=true;
try{$ocrUsed=(int)db()->fetchValue("SELECT COUNT(*) FROM ocr_usage_logs WHERE quota_day=:day AND status='success'",['day'=>$ocrQuotaDay]);}catch(\Throwable $e){$ocrCounterReady=false;}
$ocrRemaining=$ocrCounterReady?max(0,$ocrQuota-$ocrUsed):null;
$decodeOcr=function($ciphertext,$context){
 if(!$ciphertext)return [];
 try{$plain=decrypt_private_value((string)$ciphertext,$context);$data=json_decode((string)$plain,true);return is_array($data)?$data:[];}catch(\Throwable $e){return [];}
};
?>
